"""Semantic contract for the `skill-eval` catalog skill."""

from __future__ import annotations

from catalog_core import SKILLS_DIR, errors

SKILL = "skill-eval"
REQUIRED_PATHS = [
    "SKILL.md",
    "references/evaluation-contract.md",
    "scripts/skill_eval.py",
    "scripts/skill_eval_runtime/common.py",
    "scripts/skill_eval_runtime/skill_eval.py",
]
REQUIRED_TEXT = [
    "Generated by scripts/generate_p0_runtimes.py",
    "agent-skill-eval/v1",
    "baseline and treatment",
    "positive, negative, and confusable",
    "deterministic verifier",
    "shell=False",
    "changed paths",
    "relative token",
    "EXIT_GATE = 30",
    "verifier modified the workspace",
    "repository_snapshot_digest",
    "validate-result",
    "outside the isolated fixture",
    "PYTHONDONTWRITEBYTECODE",
]
FORBIDDEN_TEXT = (
    "an llm self-report is correctness evidence",
    "lower cost offsets failed correctness",
    "shell=true",
)


def validate(*, readme_text: str | None = None) -> None:
    skill_dir = SKILLS_DIR / SKILL
    missing = [relative for relative in REQUIRED_PATHS if not (skill_dir / relative).is_file()]
    if missing:
        errors.append(f"{SKILL}: missing required behavior-eval payload: {missing}")
        return
    text = "\n".join((skill_dir / relative).read_text(encoding="utf-8") for relative in REQUIRED_PATHS)
    lowered = text.lower()
    absent = [fixture for fixture in REQUIRED_TEXT if fixture.lower() not in lowered]
    if absent:
        errors.append(f"{SKILL}: behavior-eval contract fixtures missing: {absent}")
    found = [fixture for fixture in FORBIDDEN_TEXT if fixture in lowered]
    if found:
        errors.append(f"{SKILL}: unsafe evaluation semantics present: {found}")
